<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { ElMessage } from 'element-plus';
import { adminServices } from '../services/AdminServices';
import { RepositoryError } from '../repository/RepositoryError';
import { CampusRole, CampusStatus, type CampusSession, type CampusSchool, type CampusSchoolTree, type CampusCollege, type CampusMember, type CampusMaintenanceItem } from '../models/contracts';
const props=defineProps<{authorization:CampusSession}>();
const emit=defineEmits<{changed:[];'session-expired':[]}>();
const repo=adminServices.getCampus();
const schools=ref<CampusSchool[]>([]),schoolTotal=ref(0),schoolPage=ref(1),schoolKeyword=ref(''),selected=ref<CampusSchool|null>(null),tree=ref<CampusSchoolTree|null>(null),collegeId=ref(''),members=ref<CampusMember[]>([]),memberPage=ref(1),memberTotal=ref(0),memberKeyword=ref(''),contests=ref<CampusMaintenanceItem[]>([]),contestPage=ref(1),contestTotal=ref(0),contestKeyword=ref(''),section=ref('members'),busy=ref(false),error=ref('');
const platform=computed(()=>props.authorization.members.some(m=>m.role===CampusRole.Value0));
const schoolAdmin=computed(()=>props.authorization.members.some(m=>m.role===CampusRole.Value1&&m.schoolId===selected.value?.id));
const manage=computed(()=>!!selected.value&&selected.value.status===CampusStatus.Value0&&(platform.value||schoolAdmin.value));
const editing=ref(false),dialog=ref<'school'|'college'|'member'|'account'|'assignment'>('school'),original=ref<CampusSchool|CampusCollege|CampusMember|null>(null),assignment=ref<CampusMaintenanceItem|null>(null),saving=ref(false),dialogError=ref('');
const form=ref({name:'',code:'',status:CampusStatus.Value0,userId:'',password:'',displayName:'',duty:'',role:CampusRole.Value2 as CampusRole,collegeId:'',responsibleMemberId:''});
let alive=true,schoolGen=0,detailGen=0;onBeforeUnmount(()=>{alive=false;schoolGen++;detailGen++;});
function failure(e:unknown){if(e instanceof RepositoryError&&e.code===401)emit('session-expired');return (e instanceof Error?e.message:'操作失败')+(e instanceof RepositoryError&&e.code===409?'；输入已保留，关闭后刷新核对再试。':'');}
async function loadSchools(page=1){const n=++schoolGen;error.value='';try{const r=await repo.listSchools({keyword:schoolKeyword.value||undefined,page,pageSize:20});if(!alive||n!==schoolGen)return;schools.value=r.list;schoolTotal.value=r.total;schoolPage.value=page;if(selected.value){const match=r.list.find(s=>s.id===selected.value?.id);if(match)selected.value=match;}else if(r.list[0])await chooseSchool(r.list[0]);}catch(e){if(alive)error.value=failure(e);}}
async function chooseSchool(s:CampusSchool){const n=++detailGen;selected.value=s;collegeId.value='';section.value='members';tree.value=null;members.value=[];contests.value=[];error.value='';busy.value=true;try{const r=await repo.getSchoolTree(s.id);if(!alive||n!==detailGen)return;tree.value=r;await loadMembers(1);if(schoolAdmin.value)await loadContests(1);}catch(e){if(alive&&n===detailGen)error.value=failure(e);}finally{if(alive&&n===detailGen)busy.value=false;}}
async function loadMembers(page=1){const id=selected.value?.id,n=detailGen;if(!id)return;try{const r=await repo.listMembers({schoolId:section.value==='platform-members'?undefined:id,collegeId:section.value==='platform-members'?undefined:collegeId.value||undefined,keyword:memberKeyword.value||undefined,page,pageSize:20});if(!alive||n!==detailGen)return;members.value=r.list;memberTotal.value=r.total;memberPage.value=page;}catch(e){if(alive&&n===detailGen)error.value=failure(e);}}
async function loadContests(page=1){const id=selected.value?.id,n=detailGen;if(!id||!schoolAdmin.value)return;try{const r=await repo.listMaintenanceContests({schoolId:id,keyword:contestKeyword.value||undefined,page,pageSize:20});if(!alive||n!==detailGen)return;contests.value=r.list;contestTotal.value=r.total;contestPage.value=page;}catch(e){if(alive&&n===detailGen)error.value=failure(e);}}
async function chooseCollege(id:string){collegeId.value=id;section.value='members';await loadMembers(1);}
function edit(kind:typeof dialog.value,row:CampusSchool|CampusCollege|CampusMember|null=null){dialog.value=kind;original.value=row;dialogError.value='';form.value={name:row&&'name'in row?row.name:'',code:row&&'code'in row?row.code:'',status:row?.status||CampusStatus.Value0,userId:row&&'userId'in row?row.userId:'',password:'',displayName:row&&'displayName'in row?row.displayName:'',duty:row&&'duty'in row?row.duty||'':'',role:row&&'role'in row?row.role:CampusRole.Value2,collegeId:row&&'collegeId'in row?row.collegeId||'':collegeId.value,responsibleMemberId:''};editing.value=true;}
function assign(row:CampusMaintenanceItem){dialog.value='assignment';assignment.value=row;original.value=null;dialogError.value='';form.value.collegeId=row.maintenance?.collegeId||'';form.value.responsibleMemberId=row.maintenance?.responsibleMemberId||'';editing.value=true;}
const eligible=computed(()=>tree.value?.colleges.find(c=>c.college.id===form.value.collegeId)?.responsibleMembers.filter(m=>m.status===CampusStatus.Value0)||[]);
function canEditMember(m:CampusMember){return platform.value||schoolAdmin.value&&m.role===CampusRole.Value2;}
async function save(){if(saving.value)return;const f=form.value,sid=selected.value?.id;dialogError.value='';saving.value=true;try{if(dialog.value==='school'){if(original.value)await repo.updateSchool(original.value.id,{name:f.name.trim(),code:f.code.trim(),status:f.status},{ifMatch:original.value.etag});else await repo.createSchool({name:f.name.trim(),code:f.code.trim()});}
else if(dialog.value==='college'){if(!sid)throw Error('请选择高校');if(original.value)await repo.updateCollege(original.value.id,{name:f.name.trim(),code:f.code.trim(),status:f.status},{ifMatch:original.value.etag});else await repo.createCollege({schoolId:sid,name:f.name.trim(),code:f.code.trim()});}
else if(dialog.value==='member'){if(original.value)await repo.updateMember(original.value.id,{displayName:f.displayName.trim(),duty:f.duty.trim()||null,status:f.status},{ifMatch:original.value.etag});else await repo.createMember({userId:f.userId.trim(),schoolId:f.role===CampusRole.Value0?null:sid||null,collegeId:f.role===CampusRole.Value2?f.collegeId||null:null,role:f.role,displayName:f.displayName.trim(),duty:f.duty.trim()||null});}
else if(dialog.value==='account'){if(!sid)throw Error('请选择高校');await repo.createAccount({account:f.userId.trim(),password:f.password,schoolId:sid});}
else if(dialog.value==='assignment'){if(!sid||!assignment.value)throw Error('请选择赛事');await repo.assignMaintenance(assignment.value.contestId,{schoolId:sid,collegeId:f.collegeId,responsibleMemberId:f.responsibleMemberId},{expectedEtag:assignment.value.maintenance?.etag||null});}
if(!alive)return;editing.value=false;form.value.password='';ElMessage.success(dialog.value==='account'?'账号已创建；还需要添加成员授权':'保存成功');await loadSchools(schoolPage.value);if(selected.value)await chooseSchool(selected.value);emit('changed');}catch(e){if(alive)dialogError.value=failure(e);}finally{if(alive)saving.value=false;}}
onMounted(()=>loadSchools());
</script>
<template>
<section class="campus-shell">
 <el-alert title="高校 → 学院 → 负责人。赛事维护归属与学生参赛范围分开，分配不改变已公开赛事。" :closable="false"/>
 <el-alert v-if="error" :title="error" type="error" :closable="false" class="gap"/>
 <div class="campus-toolbar"><el-input v-model="schoolKeyword" placeholder="搜索高校" clearable @keyup.enter="loadSchools()"/><el-button @click="loadSchools()">查询</el-button><el-button v-if="platform" type="primary" @click="edit('school')">新增高校</el-button></div>
 <div class="campus-grid"><aside>
  <p>高校（{{schoolTotal}}）</p><div v-for="s in schools" :key="s.id" class="school-node" :class="{active:selected?.id===s.id}"><el-button link @click="chooseSchool(s)">{{s.name}} · {{s.status}}</el-button><el-button v-if="platform" link type="primary" @click="edit('school',s)">编辑</el-button></div>
  <el-pagination small layout="prev,next" :total="schoolTotal" :page-size="20" :current-page="schoolPage" @current-change="loadSchools"/>
  <template v-if="tree"><h4>{{tree.school.name}}的学院</h4><el-button link @click="chooseCollege('')">全部成员</el-button><div v-for="c in tree.colleges" :key="c.college.id" class="college-node"><el-button link :type="collegeId===c.college.id?'primary':'default'" @click="chooseCollege(c.college.id)">{{c.college.name}} · {{c.college.status}}</el-button><el-button v-if="manage" link @click="edit('college',c.college)">编辑</el-button><p v-for="m in c.responsibleMembers" :key="m.id" class="staff-node">{{m.displayName}} · {{m.status}}</p></div></template>
 </aside><main v-loading="busy" v-if="selected">
  <h3>{{selected.name}} <el-tag>{{selected.status}}</el-tag></h3>
  <div class="campus-toolbar"><el-button v-if="manage" @click="edit('college')">新增学院</el-button><el-button v-if="manage" @click="edit('account')">创建登录账号</el-button><el-button v-if="manage" type="primary" @click="edit('member')">添加成员授权</el-button><el-button @click="chooseSchool(selected)">刷新</el-button></div>
  <el-tabs v-model="section" @tab-change="section==='assignments'?loadContests(1):loadMembers(1)"><el-tab-pane label="成员与负责人" name="members"/><el-tab-pane v-if="platform" label="全平台成员授权" name="platform-members"/><el-tab-pane v-if="schoolAdmin" label="赛事分配" name="assignments"/></el-tabs>
  <template v-if="section==='members'||section==='platform-members'"><div class="campus-toolbar"><el-input v-model="memberKeyword" placeholder="搜索姓名或账号" clearable @keyup.enter="loadMembers()"/><el-button @click="loadMembers()">查询成员</el-button></div><el-table :data="members"><el-table-column prop="displayName" label="姓名"/><el-table-column prop="userId" label="账号"/><el-table-column prop="role" label="角色"/><el-table-column label="高校"><template #default="{row}">{{row.schoolId===selected?.id?selected?.name:schools.find(s=>s.id===row.schoolId)?.name||row.schoolId||'平台'}}</template></el-table-column><el-table-column label="学院"><template #default="{row}">{{tree?.colleges.find(c=>c.college.id===row.collegeId)?.college.name||row.collegeId||'校级 / 平台'}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="canEditMember(row)" link type="primary" @click="edit('member',row)">编辑 / 停用</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next,total" :total="memberTotal" :page-size="20" :current-page="memberPage" @current-change="loadMembers"/></template>
  <template v-else-if="section==='assignments'&&schoolAdmin"><div class="campus-toolbar"><el-input v-model="contestKeyword" placeholder="搜索赛事，如挑战杯" clearable @keyup.enter="loadContests()"/><el-button @click="loadContests()">查询赛事</el-button></div><el-table :data="contests"><el-table-column prop="name" label="赛事" min-width="200"/><el-table-column label="公开状态"><template #default="{row}">{{row.takedown?'已下架':row.publishedVersionId?'已公开':'未公开'}}</template></el-table-column><el-table-column label="负责学院"><template #default="{row}">{{tree?.colleges.find(c=>c.college.id===row.maintenance?.collegeId)?.college.name||'待分配'}}</template></el-table-column><el-table-column label="负责人"><template #default="{row}">{{tree?.colleges.flatMap(c=>c.responsibleMembers).find(m=>m.id===row.maintenance?.responsibleMemberId)?.displayName||'待分配'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" :disabled="!manage" @click="assign(row)">分配 / 调整</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next,total" :total="contestTotal" :page-size="20" :current-page="contestPage" @current-change="loadContests"/></template>
 </main></div>
 <el-dialog v-model="editing" :title="dialog==='school'?'高校资料':dialog==='college'?'学院资料':dialog==='member'?'成员授权':dialog==='account'?'创建登录账号':'分配赛事负责人'" width="540px" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving">
  <el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/>
  <el-form label-position="top" :disabled="saving">
   <template v-if="dialog==='school'||dialog==='college'"><el-form-item label="名称"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="代码（高校全局唯一，学院校内唯一）"><el-input v-model="form.code" maxlength="50"/></el-form-item></template>
   <template v-if="dialog==='account'"><el-form-item label="账号（3—64位字母数字或_.-）"><el-input v-model="form.userId" autocomplete="off"/></el-form-item><el-form-item label="初始密码（至少10位，由管理员单独告知负责人）"><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-alert title="创建账号后，还需添加成员授权才能登录管理端。" :closable="false"/></template>
   <template v-if="dialog==='member'"><el-form-item label="已有登录账号"><el-input v-model="form.userId" :disabled="!!original"/></el-form-item><el-form-item label="姓名 / 显示名称"><el-input v-model="form.displayName" maxlength="100"/></el-form-item><el-form-item label="管理角色"><el-select v-model="form.role" :disabled="!!original"><el-option :label="CampusRole.Value2" :value="CampusRole.Value2"/><el-option v-if="platform" :label="CampusRole.Value1" :value="CampusRole.Value1"/><el-option v-if="platform" :label="CampusRole.Value0" :value="CampusRole.Value0"/></el-select></el-form-item><el-form-item v-if="form.role===CampusRole.Value2" label="负责学院"><el-select v-model="form.collegeId" :disabled="!!original"><el-option v-for="c in tree?.colleges.filter(c=>c.college.status===CampusStatus.Value0)||[]" :key="c.college.id" :label="c.college.name" :value="c.college.id"/></el-select></el-form-item><el-form-item label="职责说明"><el-input v-model="form.duty" type="textarea" maxlength="500"/></el-form-item><p class="muted">账号、角色和归属不能直接改动；需要调整时停用旧授权，再创建新授权。</p></template>
   <template v-if="dialog==='assignment'"><p>{{assignment?.name}}</p><el-form-item label="负责学院"><el-select v-model="form.collegeId" @change="form.responsibleMemberId=''" ><el-option v-for="c in tree?.colleges.filter(c=>c.college.status===CampusStatus.Value0)||[]" :key="c.college.id" :label="c.college.name" :value="c.college.id"/></el-select></el-form-item><el-form-item label="负责人"><el-select v-model="form.responsibleMemberId"><el-option v-for="m in eligible" :key="m.id" :label="m.displayName+' · '+m.userId" :value="m.id"/></el-select></el-form-item><el-alert title="审核中的赛事不能调整负责人；分配不改变学生端参赛范围。" :closable="false"/></template>
   <el-form-item v-if="original" label="状态"><el-select v-model="form.status"><el-option v-for="s in Object.values(CampusStatus)" :key="s" :label="s" :value="s"/></el-select></el-form-item>
  </el-form><template #footer><el-button :disabled="saving" @click="editing=false;form.password=''">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template>
 </el-dialog>
</section>
</template>
<style scoped>
.campus-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;margin-top:18px}.campus-grid aside{background:#f5f7fb;padding:16px;border-radius:12px}.campus-grid main{min-width:0}.campus-toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.campus-toolbar .el-input{max-width:280px}.school-node{padding:8px;border-radius:8px}.school-node.active{background:#e7efff}.college-node{margin:12px 0}.staff-node{padding-left:20px;margin:6px 0;color:#667085;font-size:13px}.muted{color:#667085;font-size:13px}.gap{margin-top:12px}@media(max-width:850px){.campus-grid{grid-template-columns:1fr}}
</style>
